quests[8271] = { id = 8271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Stormpike", sourceObjective = "Als ein Held der Stormpike, dürft Ihr Euch eines dieser erst kürzlich geplün… äh, wiederentdeckten Schätze, aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8272] = { id = 8272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Frostwolf", sourceObjective = "Was ist das für ein Gefühl, {name}? Wie fühlt es sich an, die Linien des Feindes zu zerschmettern und jeglichen Widerstand auszulöschen? Es ist ein gutes Gefühl, nicht wahr?\n\nFür Eure Heldentat habt Ihr eine große Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[8273] = { id = 8273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orans Dankbarkeit", sourceObjective = "Ach das ist ja interessant! Ihr sagt, Ihr habt diese Schrifttafel auf einer kleinen, unbewohnten Insel nahe der Aussichtsklippen im Hinterland gefunden, {class}? Wirklich äußerst interessant. \n\nIch danke Euch für Eure Bemühungen in dieser Angelegenheit. Unsere dunkle Fürstin wird mit dieser Entdeckung sehr zufrieden sein. Erlaubt mir, Euch angemessen zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8275] = { id = 8275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Silithus", description = "Ihr Helden der Allianz, horcht auf! Die Bedrohung durch die Silithiden blieb zu lange unbeachtet. Ohne einen wirklichen Gegner, der sie bekämpft, haben sie sich die ganze Zeit über auf eine großangelegte Invasion vorbereitet.\n\nDer Zirkel des Cenarius sammelt seine Streitkräfte in Silithus, um diesen verachtungswürdigen Kreaturen den Krieg zu erklären. Alle kampftauglichen Abenteurer werden hiermit aufgerufen, sich uns anzuschließen!\n\nWartet nicht, bis es zu spät ist! Helft uns bei der Verteidigung von Azeroth! Meldet Euch für genauere Informationen bei Windruferin Proudhorn auf Burg Cenarius.", completion = "Hervorragend, wieder ein Rekrut, der dem Aufruf gegen die Silithiden gefolgt ist. Willkommen auf Burg Cenarius, {class}. Es freut mich zu sehen, dass unsere Abgesandten auch Helden von Eurem Kaliber erreicht haben. An diesem Ort mangelt es wahrlich nicht an Aufgaben, mit denen Ihr unsere Sache unterstützen könnt. Ich denke, Ihr werdet Euch sehr schnell als unverzichtbarer Verbündeter erweisen.", objectives = "Sprecht mit Windruferin Proudhorn auf Burg Cenarius in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8276] = { id = 8276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Silithus", description = "Ihr Helden der Horde, horcht auf! Es gibt eine Bedrohung dort draußen, die wir zu lange ignoriert haben. Erderschütterungen in der Nähe von Silithidnestern, verursacht durch massive Wanderungen dieser Biester, haben unsere Aufmerksamkeit erregt. Es scheint als bereiten sie ihre weitere Expansion vor.\n\nDer Zirkel des Cenarius sammelt seine Streitkräfte in Silithus, um diesen Silithiden den Krieg zu erklären, bevor es zu spät ist. Niemals wieder, sollen diese Biester unsere Ländereien entweihen!\n\nAlle kampftauglichen Abenteurer sollten sich umgehend bei Windruferin Proudhorn auf Burg Cenarius melden. Mögen die Silithiden endgültig besiegt werden!", completion = "Hervorragend, wieder ein Rekrut, der dem Aufruf gegen die Silithiden gefolgt ist. Willkommen auf Burg Cenarius, {class}. Es freut mich zu sehen, dass unsere Abgesandten auch Helden von Eurem Kaliber erreicht haben. An diesem Ort mangelt es wahrlich nicht an Aufgaben, mit denen Ihr unsere Sache unterstützen könnt. Ich denke, Ihr werdet Euch sehr schnell als unverzichtbarer Verbündeter erweisen.", objectives = "Sprecht mit Windruferin Proudhorn auf Burg Cenarius in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8277] = { id = 8277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliches Wüstengift", description = "Beetix Ficklespragg ist Euch zu Diensten! Mein Cousin Noggle hat es sich zum Lebensinhalt gemacht, seltene Kräuter für die Alchimisten der Burg Cenarius zu sammeln. Oder hatte es zumindest, egal. Er kam von seinem letzten Ausflug mit einer starken Vergiftung zurück.\n\nIch habe es geschafft die Wirkung des Gifts zu verlangsamen, aber um es vollständig neutralisieren zu können, benötige ich Giftproben von was auch immer ihn gestochen haben mag.\n\nNoggle kam aus dem Norden, daher verwette ich mein letztes Hemd darauf, dass es Steinpanzerskorpide oder Sandhuscher waren. Bringt mir ein paar Stachel und Giftzähne und ich werde versuchen ein Gegengift für ihn zu erstellen.", progress = "Habt Ihr alle Proben zusammengesammelt? Wir können Noggle jede Minute verlieren!", completion = "Lasst uns die Daumen drücken! Hoffen wir, dass Noggle damit gerettet werden kann!", objectives = "Beetix Ficklespragg von der Burg Cenarius in Silithus möchte, dass Ihr 8 Stachel von Steinpanzerskorpiden und 8 Giftzähne von Sandhuschern für sie sammelt. Kehrt zu ihr zurück, sobald Ihr diese Aufgabe erfüllt habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8278] = { id = 8278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggles letzte Hoffnung", description = "Verflucht! Das Gegengift hat nicht gewirkt. Noggle muss von einer der stärkeren Kreaturen im fernen Süden gestochen worden sein.\n\nIch werde Euch brauchen, um dorthin zu gehen und mir noch mehr Proben zu besorgen, {name}. Das Gute dabei - da ihr Gift stärker ist, werde ich nicht so viele brauchen. Der Haken ist allerdings, dass in der südlichen Gegend mehrere Arten giftiger Kreaturen herumfleuchen und Ihr daher verschiedene Proben besorgen müsst.", sourceObjective = "Beetix Ficklespragg von der Burg Cenarius in Silithus möchte, dass Ihr je 3 Stachel von Steinpanzerzangen und Steinpanzerschindern, sowie 3 Felspirschergiftzähne für sie sammelt.", progress = "Das ist Eure letzte Chance, um Noggle zu retten! Beeilt Euch!", completion = "Ja! Es scheint zu wirken, Noggle kommt wieder zu sich. Wir sind Euch was schuldig!", sourceObjectiveStatus = "unverified-source-field" }
quests[8279] = { id = 8279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Lexikon der Twilight", description = "Die Twilight-Hammer sind nicht gerade zimperlich mit denen, die ihre Reihen verlassen wollen. Sie jagen mich bis heute, als sei ich ein wildes Tier. Unnötig zu erwähnen, dass ihre Feinde meine Freunde sind!\n\nUm diese Schrifttafel zu entschlüsseln, benötige ich das Kodebuch, welches ihre Schreiber benutzt haben, um geheime Nachrichten zu dekodieren: Das Lexikon der Twilight. Es ist dermaßen wertvoll, dass sie es in drei Kapitel aufgeteilt haben, welche an drei unterschiedlichen Orten aufbewahrt werden! Die Offiziere, denen die Teile des Lexikons anvertraut wurden, sind als Bewahrer der Twilight bekannt. Sucht in den Lagern der Twilight-Hammer nach ihnen.", sourceObjective = "Bringt Ortell dem Einsiedler in Silithus die drei Kapitel des Lexikons der Twilight.", progress = "Wer ist da? Oh, Ihr seid es! Habt Ihr schon alle Kapitel des Lexikons gefunden?", completion = "Ja! Dies sind alle Teile des Buchs! Fangen wir also an, {name}.\n\nErsetzt jedes dritte Wort, mit den Worten aus dem zweiten Kapitel… dann ersetzt die verbliebenen Worte, mit denen aus dem ersten Kapitel… Moment, war das nicht umgekehrt?", sourceObjectiveStatus = "unverified-source-field" }
quests[8280] = { id = 8280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung der Versorgungslinien", description = "Burg Cenarius ist von außerordentlicher strategischer Bedeutung. Ich bin davon überzeugt, dass unser Sieg über die Silithiden feststeht, solange wir sie halten können. Natürlich unter der Bedingung, dass wir die Versorgung mit Nachschubgütern aufrecht erhalten können.\n\nDie Sandwürmer in dieser Gegend stellen für unsere Nachschubkarawanen eine noch größere Gefahr dar als die Silithiden selbst. Erst heute Morgen verloren wir eine ganze Morgenkornlieferung an eine Gruppe Baggerschläger. Ich brauche Eure Hilfe, um die Bestände dieser Baggerschläger auszudünnen und um sicherzustellen, dass unsere Karawanen vor weiteren Überfällen sicher sind.", completion = "Ich bin Euch sehr dankbar. Eure Bemühungen, Burg Cenarius und seine Garnison zur schützen, zeugt von wahrer Tapferkeit!", objectives = "Windruferin Proudhorn auf Burg Cenarius in Silithus möchte, dass Ihr 15 Baggerschläger tötet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8281] = { id = 8281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkte Sicherheit", description = "Eure bisherigen Leistungen sind makellos, {name}. Dennoch, sind unsere Versorgungslinien noch lange nicht sicher. In Abwesenheit der Baggerschläger, werden ihre südlichen Artgenossen nach Norden drängen, um ihren Platz einzunehmen.\n\nIhr werdet eine ganze Reihe Baggerbrecher töten müssen, um diese Biester von unseren Versorgungslinien fernzuhalten.", sourceObjective = "Windruferin Proudhorn auf Burg Cenarius in Silithus möchte, dass Ihr 20 Baggerbrecher tötet.", completion = "Beeindruckend! Ihr habt Euch wahrhaftig als wertvoller Verbündeter in der Kriegsvorbereitung gegen die Silithiden erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8282] = { id = 8282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggles verlorener Ranzen", description = "Wo bin ich? Wo is' meine Tasche? *Keuch* Ich muss sie verloren haben, als ich vor Totenstachel, dem Riesenskorpid, geflohen bin. Bei meiner überstürzten Flucht bin ich geradewegs in ein Nest von Steinpanzerschindern gerannt.\n\nIn dem Ranzen, den ich bei mir trug, befanden sich allerlei seltene Reagenzien. Beetix und ich werden ohne sie nicht die Tränke herstellen können, die von der Burg Cenarius benötigt werden. Ich bin noch zu schwach, um wieder aufzustehen, aber ich kann es für Euch lohnend machen, wenn Ihr mir meine Reagenzien zurückbringt.\n\nIch bin Totenstachel nahe dem südlichen Gebirgszug über den Weg gelaufen, hinter Bronzebeards Lager.", progress = "Habt Ihr meine Tasche noch immer nicht gefunden? Nun, ich sollte zumindest froh sein, dass das Gift zu wirken aufgehört hat.", completion = "Ja! Ihr habt meinen Ranzen zurückgebracht. Sogar all meine seltenen Reagenzien sind noch da! Ich werde für lange Zeit in Eurer Schuld stehen.", objectives = "Spürt Noggles Ranzen im südlichen Gebirge von Silithus auf und bringt ihn zu ihm, auf Burg Cenarius, zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8283] = { id = 8283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Totenstachel, Terror der Wüste", description = "Man sagt, dass sich der grausame Skorpid Totenstachel nahe des südlichen Gebirgszuges wegen erhöhter Silithidenaktivität zurückgezogen hat. Dies stellt eine große Bedrohung für Patrouillen und Expeditionen in der südlichen Gegend dar. Wer sich an dessen Vernichtung beteiligt, soll reichlich belohnt werden. Fragt bei Captain Vish Kozus, ganz oben auf dem Wachturm der Burg Cenarius, wegen der Belohnung nach.", progress = "Ich brauche die Zange der Kreatur als Beweis für Eure Heldentat. Keine Zange, keine Belohnung.", completion = "Ausgezeichnet! Mit dem Tod Totenstachels steht uns der südliche Gebirgszug als strategischer Pfad zum Umgehen der Silithidschwärme wieder offen. Man schätzt Eure Leistung hier sehr.", objectives = "Bringt die Zange Totenstachels zu Vish Kozus, Captain der Wache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8284] = { id = 8284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis der Twilight-Hammer", description = "Einst existierte nordwestlich von hier ein florierender Außenposten der Twilight-Hammer. Wenn Ihr heutzutage in diese Gegend reist, werdet Ihr dort nur Schwärme von Elementaren antreffen. Verrottete Holzpfosten und alte Zelttuchfetzen sind das Einzige, was noch auf den Standort des Lagers hinweist.\n\nVor einiger Zeit fand ich dort die Fragmente einer Tontafel, allerdings nicht genug Teile, um sie zu irgendetwas Brauchbarem zusammenzusetzen. Bringt mir die fehlenden Fragmente der Schriftafel. Vielleicht können wir so etwas Licht in die Sache bringen und herausfinden, was die Twilight-Hammer in Silithus gesucht haben.", progress = "Das verwüstete Lager werdet Ihr nordwestlich von hier finden. Kommt zu mir zurück, wenn Ihr alle Fragmente gefunden habt.", completion = "Wie ich es mir gedacht habe. Ich kann zwar einige der Worte auf den Schrifttafeln entziffern, jedoch scheinen sie keiner Logik zu folgen oder irgendeine Bedeutung zu haben. Das ist nicht unbedingt ungewöhnlich, da viele Sekten der Twilight-Hammer dafür bekannt sind, ihre Texte zu verschlüsseln. Wir müssen jemanden finden, der sich besser mit solchen Sachen auskennt als wir.", objectives = "Geologin Larksbane auf Burg Cenarius möchte, dass Ihr ihr 8 Schrifttafelfragmente der Twilight bringt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8285] = { id = 8285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Deserteur", description = "Es gibt Gerüchte über ein Mitglied der Twilight-Hammer, das aus seiner Sekte desertiert ist und nun als Einsiedler in den Bergen südöstlich vom Südwindposten lebt. Sein Name ist Ortell. Vielleicht könnt Ihr ihn davon überzeugen, Euch bei der Entschlüsselung der Schrifttafel behilflich zu sein.\n\nNehmt die wiederhergestellte Schrifttafel mit Euch und sucht Ortell auf.", progress = "Ihr! Wer seid Ihr? Wie habt Ihr mich gefunden? Man hat Euch doch nicht verfolgt, oder? Sprecht!", completion = "Ah, wie ich sehe, wisst Ihr einiges über meine alte Sekte. Ihr seid ein Verbündeter des Zirkels des Cenarius, richtig?\n\nIch wette, Ihr sucht nach Informationen, die Ihr gegen die Twilight-Hammer einsetzen könnt. Kommt näher, vielleicht können wir uns gegenseitig behilflich sein.", objectives = "Bringt die wiederhergestellte Schrifttafel zu Ortell dem Einsiedler in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8286] = { id = 8286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was uns morgen erwartet", description = "Der Tod umarmte mich bereits als er erschien und seine Macht auf mich anwandte. Er ließ seinen Atem nur einmal über meinen versehrten Körper streichen und wartete daraufhin geduldig bis die Zeit meine Wunden geheilt hatte.\n\n\"Wenn es sein muss, wirst du für immer existieren\", sagte er, und mit diesen Worten sollte ich auf ewige Zeiten als Wächter gebunden sein.\n\nWerft jetzt einen Blick auf die Wüste. Der zweite Krieg steht uns bevor. Ihr müsst nach der Ruhestätte des Bronzeschwarms suchen. Reist zu den Höhlen der Zeit und seht nach, ob der Meister zurückgekehrt ist. Ich muss mir dessen sicher sein, bevor ich weiter vorgehe.", progress = "Ist Anachronos zurückgekehrt?", completion = "Es ist, wie es sein sollte! Der Eine hat sich erhoben und meine Wache neigt sich dem Ende zu…", objectives = "Reist zu den Höhlen der Zeit in Tanaris und findet Anachronos, Nachkomme Nozdormus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8287] = { id = 8287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein teuflischer Plan", description = "So, das sollte es gewesen sein… ziemlich wertvolle Informationen, muss ich sagen! Ich habe beobachtet, wie die Truppen des Zirkel des Cenarius in Silithus eingetroffen sind. Ich nehme an, sie planen die Twilight-Hammer aus Silithus zu vertreiben, nicht wahr? Diese Informationen sollten dabei hilfreich sind.\n\nBringt die Entschlüsselte Abschrift der Schrifttafel zu ihrem Anführer, Kommandant Mar'alith. Schon bald werden die Twilight-Hammer vernichtet sein und ich bin endgültig vor ihrem Zugriff sicher.", progress = "Was habt Ihr mir mitgebracht, {name}?", completion = "Das sind in der Tat sehr interessante Informationen, die Ihr mir da gebracht habt, {name}. Dies bringt etwas Licht in die Präsenz der Twilight-Hammer in Silithus und wird uns mit Sicherheit den Kampf gegen sie erleichtern. Eure Bemühungen sollen nicht unbelohnt bleiben, {class}.", objectives = "Bringt Kommandant Mar'alith die entschlüsselte Abschrift der Schrifttafel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8288] = { id = 8288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur einer kann sich erheben", description = "Wir dürfen keine Zeit mehr verschwenden! Es gilt einen Helden zu finden! Die Aufgabe, die ich Euch stellen werde, würde normalerweise eine Armee erfordern, aber nur einer aus diesem Haufen von Möchtegernhelden wird sich erheben und die Bürde und Verantwortung eines Verbündeten der Brut tragen.\n\nIm Hort des Herrschers von Blackrock befindet sich eine äußerst grausame Bestie. Der Brutwächter Dreschbringer bewacht die Hallen des Zwists und blockiert den Weg, der in Nefarians inneres Sanktum führt. Schlachtet dieses abartige Unwesen nieder und bringt mir seinen Kopf. Seid Ihr erfolgreich, erwartet Euch die nächste Aufgabe.", progress = "Ihr müsst Euch das Wohlwollen von Nozdormus Brut verdienen.", completion = "Habt Ihr Euch als Erster in tausend Jahren das Wohlwollen des Bronzeschwarms verdient?", objectives = "Bringt Brutwächter Dreschbringers Kopf zu Baristolth der Sandstürme in die Burg Cenarius in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8289] = { id = 8289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdienstabzeichen" }
quests[8290] = { id = 8290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8291] = { id = 8291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8292] = { id = 8292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdienstabzeichen" }
quests[8293] = { id = 8293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenabzeichen" }
quests[8294] = { id = 8294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silverwing", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8295] = { id = 8295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silverwing", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8296] = { id = 8296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenabzeichen" }
quests[8297] = { id = 8297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ressourcen des Arathibeckens", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, {name}. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.", sourceObjective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Sergeant Maclear in der Zuflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8298] = { id = 8298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Vorratskisten" }
quests[8299] = { id = 8299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschlagt die Versorgungslinien Arathors", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, {name}. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpünkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.", objectives = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8300] = { id = 8300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Vorratskisten" }
quests[8301] = { id = 8301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Gerechten", description = "Die Brut Nozdormus misstraut den niederen Völkern für gewöhnlich. Ihr habt mir zwar bewiesen, dass Ihr das Zeug zu einem Helden habt, es ist jedoch an der Zeit, dies auch meinem Meister zu zeigen.\n\nDer Ashischwarm, Zoraschwarm, Regalschwarm: sie alle schwärmen rege aus und sind eine Bedrohung für unsere Existenz. Vernichtet Silithiden dieser Schwärme und nehmt Euch Fragmente ihrer Knochenpanzer. Kommt zu mir zurück, wenn Ihr vom Tragen erschöpft sein solltet, auf dass ich Euch in Eurer Entschlossenheit stärken werde.", progress = "In ihrem Misstrauen gegenüber den sterblichen Völkern ist viel Geschichte verwurzelt; dies ist jedoch eine Geschichte, dessen Verkünden man besser der Brut überlässt, wenn es an der Zeit dafür ist.", completion = "Ihr seid nicht allein, Held. Ich werde Euch nun dazu befähigen, andere zu ernennen, die Euch bei Eurer Aufgabe behilflich sein können. Wenn Ihr der Held Eures Volkes sein sollt, dann braucht Ihr bei Euren Aufgaben und Pflichten Unterstützung.", objectives = "Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8302] = { id = 8302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand der Gerechtigkeit", description = "Wählt Eure Abgesandten weise aus, Sterblicher. Jedesmal, wenn Ihr nach Erfüllung Eurer Aufgabe zurückkehrt, dürft Ihr einen neuen Abgesandten auswählen.\n\nDas soll heißen, dass ich noch mehr der Knochenpanzerfragmente benötige. Verschwendet keine Zeit!", progress = "Eines Tages wird vielleicht die gesamte Burg Cenarius unter Eurer Führung stehen.", completion = "Gut gemacht, Held. Ich werde Euch nun dazu befähigen einen weiteren Agenten Nozdormus zu ernennen.", objectives = "Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8303] = { id = 8303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anachronos", description = "Es ist an der Zeit, {name}.\n\nIch muss mich dafür entschuldigen, so viel vor Euch geheim zu halten. Die Feinde sind überall, selbst unter uns. Bitte, lest aus diesem Folianten und lernt. Nutzt das Wissen, das ich Euch preisgebe, und sucht nach unserem Meister.", sourceObjective = "Sucht nach Anachronos bei den Höhlen der Zeit in Tanaris.\n\nBereitgestellter Gegenstand:", completion = "Ihr seid die Hoffnung Kalimdors, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8304] = { id = 8304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Natalia", description = "Meine geliebte Natalia ist verschwunden.\n\nUm die Wahrheit zu sagen, sie hat sich schon Wochen vor ihrem Verschwinden äußerst seltsam benommen. Ich habe sie mehr als einmal dabei erwischt, wie sie zu sich selber sprach, obwohl niemand in der Nähe war. Doch sie behauptete felsenfest, dass mit ihr alles in Ordnung sei und sie ihre Forschungen unbedingt fortsetzen müsste.\n\nDas letzte Mal hatte man sie gesehen, wie sie nach Süden, in Richtung Bronzebeards Lager verschwand.\n\nLeider stehen mir zu wenige Soldaten für weitere Nachforschungen zur Verfügung, {name}. Ich brauche Eure Hilfe, um die Zwerge in Bronzebeards Lager nach ihrem Verbleib zu befragen.", sourceObjective = "Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr die Bewohner von Bronzebeards Lager befragt. Das Lager befindet sich südlich von Burg Cenarius.\n\nKehrt zu Kommandant Mar'alith zurück, wenn Ihr die benötigten Informationen gesammelt habt.", completion = "<Kommandant Mar'alith senkt nachdenklich den Kopf>\n\nOb sie noch am Leben ist oder nicht, ich muss tun, was getan werden muss. Wir müssen sie finden. Leider binden mich meine Pflichten an diesen Außenposten. Kann ich ein weiteres Mal mit Eurer Hilfe rechen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[8305] = { id = 8305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lang Vergessenes", description = "In der südlichen Wüste von Silithus, nahe der heiligen Barriere, findet Ihr eine einzelne Kristallträne. Sie ist ein Mahnmal für all die Verluste, die wir während des Krieges der Sandstürme erlitten haben. Sucht die Träne auf und blickt in ihr Innerstes, um Erleuchtung zu erfahren.", completion = "In der Nähe des Kristalls empfindet Ihr große Trauer. Dieses Gefühl ist so stark, dass Ihr glaubt, jeden Moment das Bewusstsein zu verlieren und an den Folgen der Trauer zu sterben.", objectives = "Sucht die Kristallträne und blickt in ihr Innerstes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8306] = { id = 8306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlund des Wahnsinns", description = "Ihr müsst für mich in den Bau des Regalschwarms eindringen und herausfinden, was aus meiner liebsten Natalia geworden ist, {name}. Es ist dort sehr gefährlich, also geht nicht alleine dorthin. Sprecht noch einmal mit den Zwergen, bevor Ihr Euch in den Schlund des Wahnsinns stürzt. Sie sollten Euch einige Tipps geben können, wie Ihr mit den Silithiden fertig werdet, die den Schwarmbau bewohnen.\n\nUnd {name}, sollten die Gerüchte stimmen und sie dem Wahnsinn anheim gefallen sein,... dann tut, was Ihr tun müsst.\n\n\n\n<Kommandant Mar'alith wendet sich von Euch ab>", sourceObjective = "Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr seine geliebte Natalia wiederfindet. Die von Euch gesammelten Informationen deuten darauf hin, dass Ihr sie im Bau des Regalschwarms im Süden finden könntet.\n\nSprecht noch einmal mit den Zwergen in Bronzebeards Lager, bevor Ihr Euch in den Schwarmbau begebt. Ihr Wissen könnte sich als hilfreich erweisen und sicherlich, haben sie noch einige Aufgaben für Euch.\n\nUnd {name}, denkt an die Worte des Kommandanten: \"Tut, was Ihr tun müsst...\"", completion = "<Kommandant Mar'alith umklammert voller Zorn seine Waffe.>\n\nC'Thun? WAS hat das alles zu bedeuten? Wer ist C'Thun? Wie kann dieser Teufel meine geliebte Natalia in dieses Monster verwandeln, von dem Ihr mir berichtet habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[8307] = { id = 8307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenrezept", description = "Sich an das Leben in der Wüste anzupassen ist alles andere als leicht. Ich vermisse nicht nur die Vögel und Bäume Auberdines, nein, diese ausgedörrte Gegend schränkt uns auch sehr in der Wahl unserer Nahrung ein. Ich versuche mehr über die Kräuter der Wüste zu lernen, aber es gibt nicht so viele.\n\nIch habe gesehen, dass Gruppen des Lagers der Twilight-Hammer westlich von hier Sandwürmer jagten. Sandwurmfleisch ist aber so bitter, ich kann mir einfach nicht vorstellen, wie sie es schmackhaft machen. Haltet Eure Augen offen, wenn Ihr zu ihrem Lager geht und lasst mich wissen, falls Ihr etwas von ihnen erfahrt.", sourceObjective = "Haltet beim Lager der Twilight-Hammer westlich von Burg Cenarius nach Informationen zum Zubereiten von Sandwurmfleisch Ausschau.", completion = "Dieses Buch enthält einige der gängigen und sogar ein paar ungewöhnliche Rezepte. Nach kurzem Durchblättern des Buches entdeckt Ihr ein Rezept, das Sandwurmfleisch enthält.", sourceObjectiveStatus = "unverified-source-field" }
quests[8308] = { id = 8308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Brief von Brann Bronzebeard", description = "An den Finder dieses Briefs,\n\nwenn Ihr dies lest, bin ich wahrscheinlich bereits tot oder werde es in Kürze sein. Die meisten meiner Männer sind schon tot.\n\nIch habe Informationen über einen Titanen entdeckt, über eine große Schlacht zwischen ihm und einem alten Gott. Ja, ein verdammter alter Gott. Wir haben einen uralten Tunnel nach Ahn'Qiraj entdeckt, dem ich jetzt folge.\n\nBringt diesen Brief in mein altes Lager. Kümmert Euch bitte um meinen Affen und gebt ihm ausreichen Wasser, Nahrung und die eine oder andere Umarmung.\n\n- Brann Bronzebeard, Extremforscher\n\nP.S. Achtet auf die verrückten nachtelfischen Anbeter des alten Gottes.", progress = "Bei den Göttern.", completion = "Nun, jetzt wird mir einiges klar. Solltet Ihr jemals einen Weg nach Ahn'Qiraj finden, haltet Ausschau nach dem guten Brann. Ich befürchte, ohne seinen Affen ist er hilflos.", objectives = "Liefert Brann Bronzebeards verlorenen Brief in Bronzebeards Lager im südlichen Silithus ab.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8309] = { id = 8309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenjagd", description = "Nach unseren ersten Streifzügen in die Schwarmbauten und dem darauf folgenden Wahnsinn der Herrin Mar'aliths, haben die drei Schwarmbauten damit begonnen hunderte von Insektenkriegern auszuspucken. Die erhöhte Aktivität könnte mit den Glyphen in Zusammenhang stehen, die diese merkwürdigen Kristalle in den drei Baute der Schwärme bedecken.\n\nWir müssen unbedingt Abpausbilder von diesen Glyphen anfertigen. Mit Hilfe der Abpausbilder gelingt es uns vielleicht, hinter das Geheimnis dieses Wahnsinns zu kommen.\n\nHier {name}, nehmt dieses Abschriftenset, trommelt ein paar Eurer Freunde zusammen und begebt Euch in die Schwarmbauten. Kommt erst zu mir zurück, wenn ihr die Abpausbilder aus jedem Schwarmbau beschafft habt.", sourceObjective = "Rutgar Glyphshaper in Bronzebeards Lager in Silithus möchte, dass Ihr in den Bau des Ashischwarms, Bau des Zoraschwarms und Bau des Regalschwarms eindringt und dort Abpausbilder von den glyphenverzierten Kristallen anfertigt.\n\nBenutzt das Abschriftenset für Geologen, um Abpausbilder der uralten Glyphen herzustellen. Kehrt nach Abschluss der Aufgabe zu Rutgar Glyphshaper zurück.", progress = "Wenn ihr ein durchgeknalltes Nachtelfenmädel in einem der Schwarmbauten antrefft, tut uns einen Gefallen und verpasst ihr nen' Tritt in den Hintern!", completion = "Ich werde nicht schlau aus diesen Glyphen. So etwas habe ich in meinem ganzen Leben noch nicht gesehen! Ich hoffe Frankals Forschungen können etwas Licht in das Dunkle dieser Misere bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8310] = { id = 8310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knackt den Kode", description = "Ich denke, ich kann ein Elixier entwickeln, welches uns die Entschlüsselung der Glyphen und der Sprachen der Silithiden und Qiraji sehr erleichtern wird. Was ich dafür brauche? Gut, dass Ihr fragt! Ich benötige Gehirne! Um genau zu sein, die Gehirne eines Silithiden aus jedem einzelnen Silithidenschwarm, welche die Schwarmbauten bewohnen. Bringt mir die Gehirne und Rutgars Arbeit ist vielleicht nicht umsonst gewesen.", sourceObjective = "Frankal Stonebridge in Bronzebeards Lager möchte, dass Ihr ihm jeweils ein Silithidengehirn des Zoraschwarms, Ashischwarms und des Regalschwarms bringt. Kehrt nach der Erfüllung Eurer Aufgabe zu Frankal zurück.", progress = "Geht und spielt mit dem Affen, Junge! Ich habe keine Zeit für Belanglosigkeiten.", completion = "Fantastisch! Geht nicht zu weit weg, Junge. Vielleicht haben wir noch die eine oder andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8311] = { id = 8311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlotternachtssüßigkeiten für Jesper!", description = "Ich würde gerne während der Schlotternächte zum Süßigkeitensammeln gehen, aber ich kann nicht, ich bin krank. Wenn Ihr für mich loszieht, dann werde ich Euch Eure gesammelten Süßigkeiten gegen welche eintauschen, die ich bereits hier habe! Ich glaube Ihr werdet sie mögen - sie verwandeln Euch entweder in etwas Lustiges oder Gruseliges!\n\nAlle Gastwirte in den größeren Städten verteilen während der Schlotternächte Süßigkeiten - sprecht mit ihnen und führt ihnen vor, nach was sie Euch fragen! In Ironforge verteilt auch ein kleiner Gnom namens Talvash Süßes. Sobald Ihr die Süßigkeiten habt, kommt hierher zu mir zurück!", progress = "Habt Ihr schon alle Süßigkeiten beisammen? Ich bin traurig, dass ich wegen meinem Kranksein nicht selbst gehen kann, aber zumindest fühle ich mich ein bisschen besser, weil Ihr mir aushelft...", completion = "Wow, Ihr habt sie alle! Ihr seid großartig!\n\nDanke, dass Ihr für mich Süßigkeitensammeln und Streichespielen gegangen seid. Hier, nehmt diese Kürbisdrops - Ihr findet sie bestimmt ganz toll!\n\nGruselige Schlotternächte, {name}!", objectives = "Sprecht mit den Gastwirten in Stormwind, Ironforge und Darnassus, sowie mit Talvash del Kissel in Ironforge. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.\n\nKehrt zu Jesper ins Waisenhaus von Stormwind mit einem Marzipan aus Darnassus, einer Kaugummikugel aus Gnomeregan, Nugat aus Stormwind und einem Pfefferminzbonbon aus Ironforge zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8312] = { id = 8312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlotternachtssüßigkeiten für Spoops!", description = "Ich würde gerne während der Schlotternächte zum Süßigkeitensammeln gehen, aber ich kann nicht, ich bin krank. Wenn Ihr für mich loszieht, dann werde ich Euch Eure gesammelten Süßigkeiten gegen welche eintauschen, die ich bereits hier habe! Ich glaube Ihr werdet sie mögen - sie verwandeln Euch entweder in etwas Lustiges oder Gruseliges!\n\nAlle Gastwirte in den größeren Städten verteilen während der Schlotternächte Süßigkeiten - sprecht mit ihnen und führt ihnen vor, nach was sie Euch fragen! In Sen'jin verteilt auch ein Troll namens Kali Remik Süßes. Sobald Ihr die Süßigkeiten habt, kommt hierher zu mir zurück!", progress = "Habt Ihr schon alle Süßigkeiten beisammen? Ich bin traurig, dass ich wegen meinem Kranksein nicht selbst gehen kann, aber zumindest fühle ich mich ein bisschen besser, weil Ihr mir aushelft...", completion = "Wow, Ihr habt sie alle! Ihr seid großartig!\n\nDanke, dass Ihr für mich Süßigkeitensammeln und Streichespielen gegangen seid. Hier, nehmt diese Kürbisdrops - Ihr findet sie bestimmt ganz toll!\n\nGruselige Schlotternächte, {name}!", objectives = "Sprecht mit den Gastwirten in Orgrimmar, Undercity und Thunder Bluff, sowie mit Kali Remik in Sen'jin. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.\n\nKehrt zu Spoops ins Waisenhaus von Orgrimmar mit einem Marzipan aus Thunder Bluff, einer Kaugummikugel der Darkspear, Nugat aus Orgrimmar und einem Pfefferminzbonbon aus Undercity zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8313] = { id = 8313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteiltes Wissen", description = "Das Rezept für die Zubereitung von Sandwürmern ist zwar lesbar, enthält aber Hinweise auf Kräuter und Gewürze, von denen Ihr noch nie gehört habt. Calandrath weiß vielleicht mehr über die Pflanzen, die in der Wüste wachsen, damit das Rezept einen Sinn ergibt.", progress = "Habt Ihr etwas über das Rezept erfahren können? Ich hoffe, Ihr behaltet dieses Wissen nicht für Euch selbst!", completion = "Na dann sehen wir mal...\n\nDas sieht recht verständlich aus. Sie haben ihre eigenen Bezeichnungen für einige der Kräuter, aber das dürfte nicht weiter schwer zu entschlüsseln sein. Schaut, ich zeige es Euch!", objectives = "Bringt die ausgerissene Rezeptseite zu Calandrath ins Gasthaus der Burg Cenarius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8314] = { id = 8314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Rätsels Lösung", description = "Wir stehen kurz vor einem Durchbruch, {name}. Dank der von Euch beschafften Abpausbilder ist es mir gelungen, die Glyphen auf diesem Kristallprisma nachzubilden. Es sieht so aus, als würden sie den Qiraji und anderen unbekannten Wesen dazu dienen, mit den Silithiden zu kommunizieren.\n\nLeider ist das alles, was ich aus diesen Glyphen herauskriegen konnte. Wir müssen eine Möglichkeit finden, wie wir die in den Kristallen versteckten Botschaften freilegen können.\n\nNehmt dieses glyphenverzierte Kristallprisma und bringt es Geologin Larksbane auf Burg Cenarius. Sie müsste uns weiterhelfen können.", sourceObjective = "Rutgar Glyphshaper in Bronzebeards Lager möchte, dass Ihr Geologin Larksbane auf Burg Cenarius in Silithus das glyphenverzierte Kristallprisma bringt.", progress = "Das kann doch nicht... was habt Ihr da, {name}?", completion = "Der Grund, warum die Zwerge die Glyphen nicht entschlüsseln konnten ist ganz einfach, es gibt nichts zum Entschlüsseln! Die äußere Schicht des Prismas muss exakt nach den Markierungen innerhalb des Kristalls ausgerichtet werden, damit eine Nachricht übertragen werden kann. Clever...\n\nDiese Daten zu übersetzen dürfte nicht schwer sein, doch zuerst müssen wir den Kode entschlüsseln. Was das betrifft, habe ich nur einen einzigen Anhaltspunkt auf der Oberfläche des Prismas gefunden. Vorausgesetzt, dass das Abpausbild vollständig ist, gibt es nur eine Möglichkeit... und die ist beinahe aussichtslos.", sourceObjectiveStatus = "unverified-source-field" }
quests[8315] = { id = 8315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anrufung", description = "Die Glyphen zeigen einen Abgesandten der Qiraji, wie er sich mit drei Silithiden, vor den Knochen eines großen Drachen, trifft. Über den Glyphen steht, soweit ich dass beurteilen kann, eine Art Kode. Es könnte gut sein, dass dieser Kode der Schlüssel zur Beschwörung des Abgesandten ist.\n\nIch werde eine Kopie des Glyphenkodes anfertigen, den Ihr vor den Knochen von Grakkarond in den Sand schreiben müsst. Wenn ich Recht habe, werden die Oberanführer in dem Glauben dort auftauchen, dass neue Informationen zur Übertragung bereit stehen. Streckt sie nieder und konfrontiert den Abgesandten. Er besitzt den Schlüssel für die Kristalle...", sourceObjective = "Geologin Larksbane auf Burg Cenarius in Silithus möchte, dass Ihr ihr den Kristallentriegelungsmechanismus vom Abgesandten der Qiraji beschafft.\n\nNehmt die Glyphen der Anrufung, begebt Euch zu den Knochen von Grakkarond südlich von Burg Cenarius und zeichnet sie dort in den Sand. Sollte der Abgesandte der Qiraji erscheinen, tötet ihn und nehmt den Kristallentriegelungsmechanismus an Euch. Kehrt anschließend zu Geologin Larksbane zurück.\n\nFür diese Aufgabe werdet Ihr eine kleine Armee benötigen, {name}!", progress = "Nutz die Gunst der Stunde und schlagt zu!", completion = "{name}, ich halte 20.000 Jahre alte Geschichte in meinen Händen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8316] = { id = 8316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsausrüstung", sourceObjective = "Ein Krieg wird kommen, {name}, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8317] = { id = 8317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küchengehilfe", description = "Das Rezept kommt gelegen. Ich mache mich besser an die Arbeit, damit ich ein paar geräucherte Wüstenknödel für heute bereit habe. Ich könnte dabei etwas Hilfe gebrauchen, Ihr werdet dafür auch belohnt werden.", progress = "Wie steht's mit den Knödeln?", completion = "Ausgezeichnet! Ihr seid meine Rettung! Diese Knödel sind sogar richtig gut. Ich hätte von den Twilight-Hammer eigentlich nicht so etwas Schmackhaftes erwartet.", objectives = "Calandrath von der Burg Cenarius braucht 10 geräucherte Wüstenknödel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8318] = { id = 8318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Nachrichten", description = "Einige Kultisten der Twilight-Hammer tragen mit Kauderwelsch beschriftete Papiere bei sich. Ich möchte, dass Ihr mir ein paar dieser Texte bringt, {class}.\n\nIch habe zwar keine Möglichkeit, dieses Geschreibsel zu verstehen, doch das ist nicht der springende Punkt! Mit Hilfe dieser Papiere tauschen die verschiedenen Gruppierungen der Twilight untereinander geheime Nachrichten aus. Mit jeder Nachricht, die wir aus dem Verkehr ziehen, stören wir ihre Kommunikation untereinander!", progress = "Habt Ihr die Texte?", completion = "Exzellent! Ich werde diese Texte gut verstauen, vielleicht erweisen sie sich später noch als nützlich.", objectives = "Bringt Bor Wildmane auf Burg Cenarius 10 verschlüsselte Texte der Twilight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8319] = { id = 8319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Texte der Twilight", progress = "Bringt mir weitere Texte. Es dauert nicht mehr lange, und wir haben die Twilight-Hammer aus Silithus vertrieben.", completion = "Hervorragende Arbeit! Ich werde ein gutes Wort für Euch einlegen." }
quests[8320] = { id = 8320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geolords der Twilight", description = "Die Twilight-Hammer, ein dämonischer Kult, der sich den Kräften der Zerstörung verschrieben hat, errichtet seit längerem Lager in Silithus und hält dort Tag und Nacht bizarre Rituale ab. Bisher wissen wir noch nichts über ihre Pläne, allerdings vermuten wir, dass sie in irgendeiner Verbindung zu den pulsierenden roten Kristallen stehen, die man überall in der Wüste findet.\n\nAuch wenn wir ihrem Geheimnis früher oder später auf die Spur kommen werden, so müssen wir uns zunächst auf die unmittelbare Bedrohung konzentrieren. Sucht ihre Lager im Westen auf und haltet nach den Geolords der Twilight Ausschau. Sie sind die Köpfe dieser Schlangen; genau dort müssen wir zuschlagen!", sourceObjective = "Tötet 10 Geolords der Twilight und kehrt anschließend zu Huum Wildmane auf Burg Cenarius zurück.", completion = "Ihr habt Eure Aufgabe mit Bravour erledigt, {name}! Der Verlust ihrer Geolords wird dem Kult der Twilight einen schweren Schlag versetzen. Ich hoffe nur, dass wir dadurch die Durchführung ihrer Pläne etwas verzögert haben…", sourceObjectiveStatus = "unverified-source-field" }
quests[8321] = { id = 8321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyral der Üble", description = "Wir konnten eine weitere Operationsbasis der Twilight-Hammer ausfindig machen. Es ist eine gut versteckte Höhle in der nordöstlichen Ecke von Silithus, bekannt als die Kavernen der Twilight. Der örtliche Anführer des Kultes, Vyral der Üble, residiert dort. Er ist Euer nächstes Ziel. Besiegt ihn und bringt mir seinen Siegelring.\n\nDie Kavernen der Twilight beherbergen furchterregende Schrecken, also passt auf Euch auf! Ich wünsche Euch alles gute, {name}.", sourceObjective = "Bringt Vyrals Siegelring zu Huum Wildmane auf Burg Cenarius.", progress = "{name}, konntet Ihr Vyral den Üblen besiegen? Habt Ihr seinen Siegelring?", completion = "Ihr habt es getan! Vyral ist tot! Das kann für die Vorhaben der Twilight-Hammer in Silithus nur den Untergang bedeuten. Sicher treiben sich noch mehr von ihnen herum, doch von dem heutigen Rückschlag, den Ihr dem Kult erteilt habt, werden sie sich nicht wieder so schnell erholen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8322] = { id = 8322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faule Eier", description = "Die Menschen von Southshore lieben ihr Bier und deshalb schätzen sie das Bier, das im Gasthaus von Southshore serviert wird, auch beonders. Wir können von dem Chaos während der Schlotternächte profitieren und ihre letzte Ladung Bier für Wochen - wenn nicht sogar Monate, verderben!\n\nNehmt diese faulen Eier und werft sie in den großen Braukessel im Gasthaus von Southshore. Allein Eure Anwesenheit wird für Unruhe sorgen, Ihr solltet Euch also zu verteidigen wissen!\n\nWenn Ihr Southshore dieses unvergessliche Geschmackserlebnis überbracht habt, kommt hierher zu mir auf's Fest zurück!", progress = "Der Kessel ist voller Bier.", completion = "Nachdem Ihr Euch erfolgreich bis ins Gasthaus durchgeschlagen habt, werft Ihr jetzt die Eier in den großen Kessel. Ihr riecht bereits, wie der faulige Gestank die Luft verpestet...", objectives = "Werft die faulen Eier in den großen Braukessel im Gasthaus von Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8323] = { id = 8323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrer Glauben", description = "Jetzt, da sich das Lexikon der Twilight in meinem Besitz befindet, möchte ich Euch um einen kleinen Gefallen bitten.\n\nMeine ehemalige Organisation verschickt in regelmäßigen Abständen eine verschlüsselte Postille.\n\nSollten sie bei ihrer Suche nach mir irgendwelche Fortschritte machen, wird dies mit Sicherheit im 'Wahren Glauben' bekannt gegeben werden.\n\nAbgesehen davon, dass diese Information von großer Bedeutung für mich ist, dürfte die Postille noch weitere, für Euch interessante Informationen enthalten, die ich mit Freuden teilen werde. Bringt mir einfach alle verschlüsselten Texte, die Ihr bei den Mitgliedern der Twilight-Hammer findet.", sourceObjective = "Ortell der Einsiedler möchte, dass Ihr ihm 10 verschlüsselte Texte der Twilight beschafft.", progress = "Konntet Ihr schon einige verschlüsselte Teste ergattern? Ich kann es kaum erwarten, die aktuelle Ausgabe des 'Wahren Glaubens' zu lesen.", completion = "Hervorragend! Ich werde die Texte schnellstmöglich entschlüsseln. Sollte ich irgendetwas, dass für Euch von Interesse sein könnte finden, werde ich Euch irgendwie eine Nachricht zukommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8324] = { id = 8324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fester Glauben", progress = "Konntet Ihr noch mehr verschlüsselte Texte finden? Die Entschlüsselung wird noch eininge Zeit brauchen, also bringt mir ruhig einen großen Stapel Texte.", completion = "Hervorragend! Ich kann es kaum erwarten, sie zu lesen. Hört nicht auf und bringt mir auch weiterhin alle verschlüsselten Texte, die Ihr findet." }
quests[8325] = { id = 8325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung der Insel der Sonnenwanderer", description = "Je früher Ihr mit Eurer Ausbildung anfangt, {name}, umso besser für uns alle. Wir können uns keine Fehler erlauben, also hört gut zu.\n\nDie brennenden Kristalle - die grünen, schwebenden Objekte westlich des Sonnenturms hier - wurden lange Zeit als Energiequelle für die Experimente der Insel verwendet. Die Manawyrms waren ihre Wächter, aber der Einmarsch der Geißel in Quel'Thalas hat sie auf Grund unserer mangelnden magischen Kontrolle über sie fehlgeleitet.\n\nUns bleibt keine andere Wahl, als sie für die Wiedereroberung der Insel in ihrer Zahl zu reduzieren. Kehrt nach Beendigung Eurer Arbeit zu mir zurück.", sourceObjective = "Tötet 6 Manawyrms; sie halten sich rund um die brennenden Kristalle auf, die man nahe des Turms und des Vorbaus findet.", progress = "Der Wiederaufbau unserer Gesellschaft beginnt hier, {name}. Sind wir erst einmal in der Lage, unser Zuhause zu beschützen, können wir vorausschauen und weitersehen.", completion = "Ihr habt Eure erste Aufgabe erfolgreich gemeistert; lasst mich Euch dafür danken. Ein derartiger Erfolgt bestärkt mich in meinem Glauben, dass Ihr Euch besser anstellen werdet als diese jungen Blutelfen, die sich nicht an die Vorgaben ihrer Meister halten. Weitere Leistungen wie diese werden belohnt werden - nicht nur mit Wissen, sondern auch mit greifbaren Belohnungen.\n\nDennoch, Eure Arbeit hier ist noch nicht getan. Es gibt noch viel zu lernen, mein Kind...", sourceObjectiveStatus = "unverified-source-field" }
quests[8326] = { id = 8326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedauerliche Maßnahmen", description = "Eure Bemühungen haben uns etwas erkennen lassen, von dem ich hoffte, es wäre nicht wahr. Die unkontrollierte Macht der brennenden Kristalle hat einen viel größeren Teil des natürlichen Gleichgewichts der Insel durcheinander gebracht als ich vermutet habe. Wir müssen jetzt leider bedauerliche Maßnahmen ergreifen, um die Kontrolle wiederzuerlangen.\n\nDie Luchse aus der Umgebung sind dem Einfluss der Kristalle erlegen und müssen bekämpft werden. Bringt mir ihre Halsbänder, {name}. Noch kann ich vielleicht einen Magieschutz anfertigen, der manche wieder dem Einfluss entziehen kann.", sourceObjective = "Sammelt 8 Luchshalsbänder von erlegten Bachtatzenluchsen und Bachtatzenjungen ein. Kehrt zu Magistrix Erona auf der Insel der Sonnenwanderer zurück, sobald Ihr Eure Aufgabe erfüllt habt.", progress = "Es bereitet mir keine Freude, Euch um die Vernichtung dieser Kreaturen zu bitten. Wir haben in der Vergangenheit stets in Harmonie mit den Geschöpfen des Waldes gelebt, aber heute ist es anders. Der Grundsatz der Sin'dorei lautet Überleben; vergesst das nie.", completion = "Der Turm und die unmittelbare Umgebung sollten jetzt einigermaßen sicher sein, zumindest vorerst. Dank Euch haben wir an Sicherheit gewonnen, aber es gilt die Kontrolle über die ganze Insel wiederzuerlangen, wenn wir hier auf Dauer überleben wollen. Es wird weitaus mehr verlangen, als Manawyrms und Luchse auszulöschen.\n\nNehmt dies, {name} - es wird Euch bei Euren künftigen Taten sicherlich von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8327] = { id = 8327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichterstattung an Lanthan Perilon", description = "Erstattet meinem Assistenten Lanthan Perilon Bericht. Er wird Euch sagen, was es als Nächstes zu tun gilt. Während wir hier am Sonnenturm weiterhin über die brennenden Kristalle walten, werdet Ihr Euch auf eine dringendere Angelegenheit bezüglich der Akademie von Falthrien konzentrieren. Lanthan wird Euch alles erklären, wenn Ihr mit ihm sprecht.\n\nGeht einfach von hier aus gen Westen entlang des Pfads, Ihr solltet ihn in der Nähe antreffen.\n\nViel Glück, {name} - jeglicher Erfolg soll belohnt werden.", sourceObjective = "Sprecht mit Lanthan Perilon auf der Insel der Sonnenwanderer. Er steht in der Nähe des Pfads, der vom Sonnenturm Richtung Westen verläuft.", completion = "Magistrix Erona sagte mir bereits, dass Ihr schon bald hier sein würdet, {name}. Es steht sehr schlecht um die Akademie von Falthrien, das große schwebende Gebäude mit den kunstvollen Türmchen, das westlich von uns liegt. Ihr werdet den Rückeroberungsversuch gegen einen Getriebenen anführen - einen Blutelfen, der ihrer erbärmlichen Gier auf ewig verfallen ist.\n\nIch hoffe Ihr seid bereit. Dies wird Euch nicht nur einiges über Gefahren lehren, sondern auch etwas über das Schicksal, das Euch ereilt, wenn Ihr Eure Existenz leugnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8328] = { id = 8328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Magier", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Die Lehrerin für junge Magier hier auf der Insel der Sonnenwanderer ist Julia Sonnensturm. Sprecht mit Julia, um herauszufinden, welche Ausbildung sie Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nJulia - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", sourceObjective = "Sprecht mit Julia Sonnensturm - der Magierlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[8329] = { id = 8329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Krieger", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Der Lehrer für junge Krieger hier auf der Insel der Sonnenwanderer ist Delios. Sprecht mit ihm, um herauszufinden, welche Ausbildung er Euch anbieten kann. Die Ausbildung hat ihren Preis, habt also ein paar Münzen bei Euch.\n\nDelios - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms auf der unteren Ebene anzutreffen.", sourceObjective = "Sprecht mit Delios - dem Kriegerlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[8330] = { id = 8330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "olanian's Belongings", description = "Bei dem Chaos hier beim Sonnenturm, habe ich es nicht geschafft, all mein Hab und Gut zusammenzusammeln, das ich an verschiedenen Plätzen auf der Insel gelassen habe. Ich muss hier beim Sonnenbrunnen weiterhin Wache halten, aber könntet Ihr vielleicht meine Sachen an meiner Stelle suchen gehen?\n\nIch brauche meine Seherkugel, meine Rolle der Geißelmagie und mein Tagebuch. Nutzt diesen Ranzen für zusätzliches Gepäck, da die Dinge etwas sperrig sind. Bringt sie zu mir zurück und ich gebe Euch dafür etwas im Austausch - für Eure Mühe, versteht Ihr? Den Ranzen könnt Ihr dann auch behalten!", sourceObjective = "Sammelt Brunnenbehüter Solanians Seherkugel, seine Rolle der Geißelmagie und sein Tagebuch ein. Ihr findet die Gegenstände auf der Insel der Sonnenwanderer bei dem Tümpel, dem Brunnen und bei einem der brennenden Kristalle. Bringt sie zu dem Brunnenbehüter oben im Sonnenturm auf der Insel der Sonnenwanderer, sobald Ihr alle gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8331] = { id = 8331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aurel Goldleaf", description = "{name}, wir hatten angenommen, dass wir die Operationen der Twilight-Hammer in Silithus verlangsamt haben… bedauerlicherweise lagen wir falsch. Durch verschiedene Unternehmungen gegen den Kult, haben wir herausgefunden, dass eine noch viel dunklere Macht hinter den Twilight-Hammern steht, der sogenannte abyssische Rat. Er kontrolliert den Kult über die arkanen Windsteine, die in den Lagern der Twilight postiert sind. Daher, {name}, werdet Ihr als nächstes gegen den abyssischen Rat ins Feld ziehen.\n\nSprecht mit Aurel Goldleaf im östlichen Teil von Burg Cenarius. Für unseren nächsten Schachzug werden wir ihre Hilfe benötigen.", sourceObjective = "Sprecht mit Aurel Goldleaf auf Burg Cenarius.", completion = "Guten Tag, {name}. Mir wurde gesagt, dass Ihr Euch mit dem abyssischen Rat messen wollt? Wenn dem so ist, hört mir genau zu…", sourceObjectiveStatus = "unverified-source-field" }
quests[8332] = { id = 8332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürsten des Rates", description = "Wir glauben, es sollte möglich sein, mit Hilfe eines der Windsteine, einen der Fürsten des abyssischen Rates in eine Falle zu locken. Um das zu bewerkstelligen, werdet Ihr den Rat mit einem der Windsteine kontaktieren müssen. Dann gilt es, Euer Gegenüber davon zu überzeugen, dass Ihr ein Offizier, mittleren Ranges, der Twilight-Hammer seid.\n\nFür Euren Täuschungsversuch werden wir auf jeden Fall die Nachbildung eines Standesmedallions der Twilight benötigen. Ich kann ein solches Medallion anfertigen, allerdings brauche ich dafür einen großen glänzenden Splitter und das Wappen eines abyssischen Templers.\n\nBringt mir diese Komponenten und ich fertige Euch das Medallion an.", sourceObjective = "Bringt Aurel Goldleaf auf Burg Cenarius 1 großen glänzenden Splitter und 3 abyssische Wappen.", progress = "Ah, {name}, habt Ihr den Splitter und die Wappen? Nur mit diesen Komponenten kann ich Euch das Standesmedallion eines Twilightkultisten anfertigen.", completion = "Ah, sehr gut. Das Medallion ist fast fertiggestellt. Wartet kurz, während ich Eure Komponenten in das Medallion einarbeite…\n\nDas hätten wir. Hier ist das Medallion, {name}.\n\nIhr müsst das Medallion tragen, wenn Ihr einen der Windsteine der Twilight-Hammer aktiviert. Solange Ihr das Medallion und den restlichen Twilightzierat tragt, wird Euch der abyssische Rat für einen ihrer niederen Kultisten halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8333] = { id = 8333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Standesmedallion", progress = "Falls Ihr ein weiteres Standesmedaillon eines Twilightkultisten braucht, helfe ich Euch gerne weiter. In jedem Fall benötige ich jedoch einen weiteren glänzenden Splitter und einige abyssische Wappen…", completion = "Hier, nehmt es, {name}. Ein weiteres Standesmedaillon der Twilight. Nutzt es weise, und alles Gute für Euren Kampf gegen den abyssischen Rat!" }
quests[8334] = { id = 8334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressivität", description = "Bevor ich Euch zur Akademie aussende, möchte ich, dass Ihr Euch um eine andere Aufgabe kümmert, die es sofort zu erledigen gilt. Einst halfen uns die Borklinge, die Pflanzenwelt der Insel der Sonnenwanderer zu erhalten, aber jetzt sind uns diese Bestien außer Kontrolle geraten. Helft uns so schnell wie möglich bei ihrer Vernichtung, aber seid gewarnt - der Verlust ihrer Kontrolle hat sie äußerst aggressiv werden lassen. Es ist diese Angriffslust, die uns zwingt, diese einst friedlichen Untergebenen zu zerschlagen.\n\nEs bereitet mir keine Freude, Euch um diesen Gefallen zu bitten, aber es geht nun mal ums Überleben. Ich werde später trauern.", sourceObjective = "Tötet 7 Borklinge und 7 wilde Borklinge. Kehrt dann zu Lanthan Perilon auf der Insel der Sonnenwanderer zurück.", completion = "Der Tod der Borklinge macht mich zwar nicht glücklicher, aber es beweist mir, dass Ihr für die wichtigste Aufgabe hier auf der Insel der Sonnenwanderer bereit seid. Nehmt dies und setzt es mit Bedacht ein; Ihr werdet gute Waffen und einen scharfen Verstand für Euren nächsten Auftrag brauchen. Es liegt an Euch, ob wir die Kontrolle über die Insel erfolgreich wiedererlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8335] = { id = 8335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felendren der Verbannte", description = "Einer unserer Verräter haust oben in der Akademie von Falthrien im Südwesten.\n\nFelendren ist sein Name. Er wurde aus dem Reich der Blutelfen verbannt, da er die Warnungen unserer Lehrer und Ältesten missachtet hat. Er ist der Schlimmste unserer Art, da er nur nach der Befriedigung seines unstillbaren Magieverlangens strebt. Er hat sich der Kontrolle verweigert und ist nur noch ein Schatten seines einstigen Selbsts – ein Getriebener – und er stellt eine Bedrohung für den Sonnenturm dar.\n\nVernichtet ihn und die Gespenster, die er sich als Diener zu Nutzen macht.", sourceObjective = "Tötet 8 Arkangespenster, 2 besudelte Arkangespenster und Felendren den Verbannten. Ihr findet sie in der Akademie von Falthrien. Bringt Felendrens Kopf zu Lanthan Perilon auf der Insel der Sonnenwanderer.", progress = "Lasst Euch gewarnt sein - Felendren der Verbannte ist nur das Anzeichen eines viel größeren Problems. Sein Untergang wird lediglich unsere momentanen Schwierigkeiten lösen. Allen Blutelfen könnte das gleiche Schicksal wie ihn ereilen, sollten wir unserem Verlangen gänzlich erliegen.", completion = "Felendrens Kopf... Ihr verdient Lob, {name}. Wo andere, wie Felendren, versagt haben, habt Ihr Euch erfolgreich gezeigt. Vielleicht seid Ihr wirklich bereit, ein gleichgestelltes Mitglied der Blutelfen zu werden.\n\nEuer Erfolg hier beweist, dass Ihr vor den größeren Bedrohungen Immersangs gefeit seid... und glaubt mir, es gibt genug davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[8336] = { id = 8336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fistful of Slivers", description = "Es ist eine Schande, dass wir die Kontrolle über so viele Kreaturen hier auf der Insel verloren haben. Es war einst ein ruhiger Ort der Studien und Forschungsarbeiten. Jetzt können wir uns nur noch hüten, damit wir von unseren eigenen Kreationen nicht angegriffen werden!\n\nIch biete Euch einen magischen Segen an, wenn Ihr für mich etwas einsammelt. Bringt mir eine Handvoll Arkanspäne von den Mana benutzenden Kreaturen der Insel der Sonnenwanderer und ich wirke einen Zauber auf Euch, welcher Eure weiteren Abenteuer immens erleichtern wird.", sourceObjective = "Sammelt 6 Arkanspäne und bringt sie zu Arkanist Ithanas auf der Insel der Sonnenwanderer. Derartige Fragmente findet man bei allen Mana benutzenden Kreaturen auf der Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[8338] = { id = 8338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelter Arkanspan", description = "Das Fragment kristallisierten Manas, das Ihr bei dem Körper des besudelten Arkangespensts gefunden habt, ist äußerst sonderbar. Es ist anders als die Fragmente, die Ihr vielleicht sonst gesehen habt. Es sieht so dunkel und unheimlich wie das Gespenst, von dem Ihr es habt, aus. Hält man es in der Hand, spürt man bereits etwas unnatürlich Bedrohliches.\n\nArkanist Helion beim Vorbau des Sonnenturms auf der Insel der Sonnenwanderer könnte für das Fragment vielleicht Verwendung finden.", sourceObjective = "Bringt den besudelten Arkanspan zu Arkanist Helion beim Vorbau des Sonnenturms auf der Insel der Sonnenwanderer.", progress = "Ich entnehme Eurer Haltung, dass es um etwas Dringliches geht. Kann ich Euch irgendwie behilflich sein?", completion = "Das ist... äußerst interessant. Mit interessant meine ich beunruhigender als alles andere.\n\nUnser Bestreben nach der Zerstörung des Sonnenbrunnens wieder die Kontrolle über diese Insel zu erlangen, war eine Herausforderung. Ich vermute, welch Übel auch immer der Grund für diese Verderbnis der Insel ist, dass das Fragment uns weitere Auskünfte über dessen Ursprung geben kann.\n\nEs war weise von Euch, damit zu mir zu kommen, {name}. Nehmt dies als Vergütung für Eure Mühen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8339] = { id = 8339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnung des Rats", description = "Um einen Siegelring eines Schattenhammerkultisten herzustellen, brauche ich ein paar Dinge.", sourceObjective = "Bringt die Gegenstände zu Aurel Goldblatt in der Burg Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8340] = { id = 8340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelring des Schattenhammers" }
quests[8341] = { id = 8341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lords des Rates", description = "Einen Lord des abyssischen Rates kann nur durch einen großen Windstein herbeigerufen werden und nur den höchstdekorierten Ratsmitgliedern der Twilight ist es erlaubt mit den Lords in Kontakt zu treten. Doch... ich habe einen Weg gefunden, um Eure Verkleidung anzupassen und somit die abyssischen Lords zu täuschen!\n\nDazu benötigen wir einen Herrschaftsring, welcher nur von den höchsten Mitgliedern des Kultus getragen wird. Ich kann Euch einen Ring anfertigen, wenn Ihr mir einige große glänzende Splitter und ein paar abyssische Siegel bringt.", sourceObjective = "Bringt Aurel Goldleaf auf Burg Cenarius 5 große glänzende Splitter und 3 abyssische Siegel.", progress = "Habt Ihr die Splitter und Wappen, {name}? Ich brauche sie, um den Herrschaftsring anzufertigen.", completion = "Habt Dank. Gebt mir einen Moment Zeit, um den Ring zu vollenden…\n\nSo, das sollte es gewesen sein. Denkt daran, den Ring, das Standesmedallion und den restlichen Twilightzierat anzulegen, bevor Ihr einen der großen Windsteine aktiviert. Wenn Ihr alles richtig gemacht habt, werden die Mitglieder des abyssischen Rates Euch für einen ihrer Gefolgsleute halten. Anschließend sollte es Euch gelingen, einen von ihnen in die Falle zu locken!", sourceObjectiveStatus = "unverified-source-field" }
quests[8342] = { id = 8342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrschaftsring der Twilight" }
quests[8343] = { id = 8343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldleafs Entdeckung", description = "{name}, Aurel Goldleaf glaubt einen Weg gefunden zu haben, eines der führenden Mitglieder des abyssischen Rates zu beschwören und zu besiegen. Diese Aufgabe wird äußerst gefährlich werden und ihr genießt den größten Respekt innerhalb des Zirkels des Cenarius. Daher glauben wir, dass wenn es jemanden gibt, der diese schwere Prüfung meistern kann, dann seid ihr es.\n\nMöge Euch das Schicksal gnädig sein, {name}! Sprecht mit Aurel, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Aurel Goldleaf auf Burg Cenarius.", completion = "Was Huum sagt, entspricht der Wahrheit. Ich denke, ich weiß, wie ich einen der Lords des abyssischen Rates beschwören kann! Ich werde es Euch erklären, hört genau zu…", sourceObjectiveStatus = "unverified-source-field" }
quests[8344] = { id = 8344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel zur Macht", description = "Erhört meine Worte, Kind - diese Insel ist von einem Makel behaftet, der mächtiger als die Überbleibsel der Geißel ist.\n\nIch glaube, dass auf der Insel eine wirklich dämonische Präsenz vorherrscht.\n\nWestlich von hier liegen die Türme der Akademie von Falthrien. Die Arkangespenster, die dort hausen, sind der Schlüssel zu der dämonischen Machtquelle. Bringt mir Essenzen von besudelten und unbesudelten Gespenstern.\n\nIm Austausch für Euren Gehorsam, werde ich Euch lehren, wie man einen Wichtel als Begleiter beschwören kann - Euren ersten von vielen als Hexenmeister.Ihr erlernt:", sourceObjective = "Bring 4 Essenzen eines Gespenstes und 1 Essenz eines besudelten Gespenstes zu Beschwörer Teli'Larien beim Sonnenturm auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[8345] = { id = 8345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Shrine of Dath'Remar", description = "Tag für Tag stehe ich hier, beobachte, warte. Man hat mich beschuldigt, zu tief in unserer Vergangenheit zu graben, während mein Blick zum Horizont gerichtet ist. Ich glaube jedoch fest daran, dass jeder Besucher dieser Insel diejenigen ehren sollte, die alles dafür geopfert haben, damit andere fortfahren können.\n\nDath'Remar Sonnenwanderer war unser erster König. Er führte uns durch den Mahlstrom von Kalimdor hierher.\n\nSucht seinen Schrein im Westen auf und kehrt erst dann zu mir zurück, wenn Ihr die dort angebrachte Tafel zu seiner Ehre gelesen habt.", sourceObjective = "Lest die Tafel am Schrein von Dath'Remar und kehrt anschließend zu Brunnenbehüter Solanian beim Sonnenturm auf der Insel der Sonnenwanderer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8346] = { id = 8346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hirst Unending", description = "Wenn es eine Lektion von Eurer Zeit auf der Insel der Sonnenwanderer gibt, die Ihr niemals vergessen dürft, dann ist es diese: Verliert unter keinen Umständen die Kontrolle über Euer Verlangen nach Magie. Dieser Durst ist unstillbar, {name}. Verwendet den arkanen Strom, um das, was Ihr absorbiert, zu kontrollieren und in der von Euch gewünschten Form wieder freizulassen. Begeht Ihr dabei einen Fehler, werdet Ihr zu einem Getriebenen... hoffnungslos abhängig und dem Wahnsinn verfallen.\n\nSucht nach einem Manawyrm und fokussiert Euren Manadurst auf ihn. Lernt, Eure Macht zu kontrollieren. Kehrt zu mir zurück, wenn Ihr einen arkanen Strom entfesselt habt - und das zufriedenstellend.", sourceObjective = "Verwendet die Volksfähigkeit 'Arkaner Strom' auf einen Manawyrm und kehrt anschließend zu Arkanist Helion zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8347] = { id = 8347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für die Kundschafter", description = "Magistrix Erona möchte, dass Ihr Euch nach Silbermond begebt, um die dortigen Bestrebungen zur Wiedereroberung zu unterstützen... allerdings gilt es vorher noch, etwas bei der Akademie von Falthrien zu erledigen. Ihr habt uns nicht enttäuscht, {name}.\n\nAuf Eurem Weg zum Falkenplatz südlich von hier solltet Ihr mit Kundschafterin Alarion sprechen. Sie ist nicht weit der Brücke.\n\nDie Kundschafter kümmern sich um den Warenverkehr zwischen hier und dem Landesinneren der Insel, und da Ihr Eure Tatkräftigkeit eindrucksvoll unter Beweis gestellt habt, denke ich, dass sie Eure Hilfe sicherlich sehr begrüßen werden.", sourceObjective = "Sprecht mit Kundschafterin Alarion nahe der Brücke, die in den Süden der Insel der Sonnenwanderer führt.", completion = "Oh, hallo {class}! Ich hörte schon, dass einer von Magistrix Eronas findigen Blutelfen sich auf den Weg hierher gemacht hat, um uns Kundschaftern ein wenig zur Hand zu gehen. Etwas Hilfe kommt uns sehr gelegen, insbesondere von jemand so tatkräftigem wie Euch.\n\nSeid Ihr bereit, ein oder zwei Botengänge für uns zu erledigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8348] = { id = 8348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Fürsten", description = "Huum hat mir erzählt, dass Ihr herausbekommen habt, wie man einen der abyssischen Fürsten herbeiruft? Eine beeindruckende Leistung, muss ich sagen.\n\nWisst Ihr, was noch beeindruckender wäre? Wenn Ihr es fertig bringt, eines dieser Dinger zu erledigen. Das sollte einen bleibenden Eindruck bei ihren Gefolgsleuten hinterlassen, wenn Ihr wisst, was ich meine. Bringt mir das Siegel des Besiegten, als Beweis Eurer Tat.", sourceObjective = "Bringt Bor Wildmane auf Burg Cenarius das abyssische Siegel.", progress = "Wie lief es mit dem abyssischen Fürsten? War er ein harter Brocken?", completion = "Seit Ihr Burg Cenarius betreten habt, war mir klar, dass Ihr ein mächtiger {class} seid. Macht weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[8349] = { id = 8349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bor Wildmane", description = "Nun, da Ihr ein Medaillon habt und in der Lage seid, einen abyssischen Fürsten herbeizurufen, sprecht mit Bor Wildmane. Er wird Euch mit einer Aufgabe, die sich gegen den abyssischen Rat richtet, beauftragen.\n\nViel Glück, {name}. Falls Ihr weitere Medaillons braucht, kehrt zu mir zurück.", sourceObjective = "Sprecht mit Bor Wildmane auf Burg Cenarius.", completion = "Es freut mich, Euch wiederzusehen, {class}! Gut, wie ich sehe, habt Ihr Euch eine Medallion anfertigen lassen. Für Eure nächste Aufgabe werdet Ihr sie brauchen…", sourceObjectiveStatus = "unverified-source-field" }
quests[8350] = { id = 8350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolgreiche Lieferung", description = "Der Tod eines weiteren Kundschafters ist eine wahre Tragödie, aber es ist ein Risiko, das wir alle in Kauf nehmen, wenn wir einen Auftrag annehmen. Magistrix Erona beim Sonnenturm möchte, dass dieses Päckchen schnellstmöglich zum Gasthaus beim Falkenplatz geliefert wird.\n\nWir haben nur noch wenige Leute und niemand könnte jetzt für uns einspringen.\n\nIch möchte Euch nichts vormachen, Ihr habt selbst gesehen, wie gefährlich die Straße zum Falkenplatz sein kann, sobald man vom Dämmerweg abkommt. Fühlt Ihr Euch bereit für diese Aufgabe, {name}?", sourceObjective = "Bringt Eronas Päckchen zu Gastwirtin Delaniel im Gasthaus beim Falkenplatz im Immersangwald.", progress = "Willkommen in meinem bescheidenen Gasthaus, {class}. Ich nehme an, Ihr habt etwas für mich?", completion = "Vielen Dank, ich weiß Eure prompte Lieferung sehr zu schätzen.\n\nWo Ihr schon mal da seid, könnt Ihr es Euch auch gleich gemütlich machen. Ich habe einige Ruhesteine im Angebot, falls Ihr noch keinen erworben habt. Mit diesem Stein könnt Ihr Euch einmal alle halbe Stunde in ein Gasthaus zurückteleportieren. Macht Euch keine Sorgen, wenn Ihr Euren Ruhestein mal verlieren solltet. Kehrt einfach zu einem Gastwirt Eurer Wahl zurück und er wird Euch mit Freuden einen neuen Stein zur Verfügung stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8351] = { id = 8351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bor möchte Euch sprechen", description = "Nun, da Ihr Euch als ein führendes Mitglied der Twilight-Hammer ausgeben könnt, bin ich sicher, dass Bor Wildmane gerne mit Euch sprechen möchte. Am besten sucht Ihr ihn gleich auf… und bereitet Euch auf eine sehr schwierige Aufgabe vor…", sourceObjective = "Sprecht mit Bor Wildmane auf Burg Cenarius.", completion = "Ja, es stimmt, {name}. Vor uns liegt eine sehr schwere Aufgabe...", sourceObjectiveStatus = "unverified-source-field" }
quests[8352] = { id = 8352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Szepter des Rates", description = "Huum und ich haben gerade über Euch gesprochen. Er erzählte mir, dass Ihr schon beinahe bereit seid, einem der abyssischen Lords entgegenzutreten!\n\nIch muss Euch warnen, das ist ein sehr gefährliches Unterfangen! Nehmt lieber Verstärkung mit, und ich meine nicht bloß ein bis zwei Eurer Freunde! Ich spreche von einer erfahrenen, kampfgestählten Truppe, die weiß, worauf sie sich einlässt. Sollten Eure Freunde aus dem gleichen Holz geschnitzt sein wie Ihr, besteht sogar eine reelle Chance, dass Ihr den Sieg davontragen werdet.\n\nFalls Ihr siegt, bringt mir wie immer einen Beweis und ich werde Euch eine wahrhaft mächtige Belohnung zuteil werden lassen.", sourceObjective = "Bringt Huum Wildmane auf Burg Cenarius ein abyssisches Szepter.", progress = "Und, wie ist es gelaufen? Ich würde beinahe alles tun, um meinen Posten nur für einen Moment verlassen zu können, um selbst eines dieser Dinger zu erlegen!", completion = "Ihr… Ihr habt es tatsächlich geschafft! Geschafft, {name}! Dies ist die größte Truhe die wir finden konnten, und ich habe sie mit den besten Sachen gefüllt, die wir finden konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8353] = { id = 8353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnchengegacker für ein Pfefferminzbonbon", description = "Ah, wir gehen also Süßigkeitensammeln für ein krankes Kind? Ich dachte mir schon, dass Ihr etwas zu alt seid, um für Süßes loszuziehen...\n\nNaja, für meine Leckerei - ein Pfefferminzbonbon aus Ironforge - müsst Ihr... wie ein Hühnchen gackern! Ja, Hühnchen lieben Pfefferminzbonbons... nun ja, OK, vielleicht LIEBEN sie sie nicht... aber ich gebe Euch trotzdem kein Pfefferminzbonbon, wenn Ihr nicht wie ein Hühnchen für mich gackert!\n\nSo {class}, seid Ihr dazu bereit oder nicht?! Verdient Euch Eure Süßigkeit!", sourceObjective = "Spielt Gastwirt Firebrew ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Ironforge geben!", progress = "Ich warte...", completion = "Was für ein Spaß! Nicht schlecht, {name}! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[8354] = { id = 8354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnchengegacker für ein Pfefferminzbonbon", description = "Ah, wir gehen also Süßigkeitensammeln für ein krankes Kind? Ich dachte mir schon, dass Ihr etwas zu alt seid, um für Süßes loszuziehen...\n\nNaja, für meine Leckerei - ein Pfefferminzbonbon aus Undercity - müsst Ihr... wie ein Hühnchen gackern! Ja, Hühnchen lieben Pfefferminzbonbons... nun ja, OK, vielleicht LIEBEN sie sie nicht... aber ich gebe Euch trotzdem kein Pfefferminzbonbon, wenn Ihr nicht wie ein Hühnchen für mich gackert!\n\nSo {class}, seid Ihr dazu bereit oder nicht?! Verdient Euch Eure Süßigkeit!", sourceObjective = "Spielt Gastwirt Norman ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Undercity geben!", progress = "Ich warte...", completion = "Was für ein Spaß! Nicht schlecht, {name}! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[8355] = { id = 8355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaugummikugelexpress", description = "Ah, Süßes oder Saures! Hussah!\n\nNun, auch wenn Ihr etwas Ehrenhaftes tut und Süßigkeiten für ein krankes Kind sammelt, so kann ich Euch doch nicht so einfach davonkommen lassen. Ich hätte da eine leckere Kaugummikugel aus Gnomeregan für das kranke Kind... wenn Ihr mir einen Zug vorführt! Haha, ja, das wär's! Der Preis für diese Kaugummikugel ist das Imitieren eines Zuges!\n\nTschugga-tschugga, {class}!", progress = "Nun, legt los...", completion = "Huu-huu! Klasse, {name}! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", objectives = "Ahmt für Talvash del Kissel einen Zug nach und er wird Euch dafür eine Kaugummikugel aus Gnomeregan geben!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8356] = { id = 8356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muskelspiel für Nugat", description = "Das ist ein... interessantes Kostüm, welches Ihr da tragt. Auch wenn Ihr nett seid und einem kranken Kind dieses Jahr beim Süßigkeitensammeln helft, so fürchte ich doch, dass ich Euch um eine kleine Vorstellung bitten muss!\n\nMal sehen... Ihr seht in diesem... Kostüm stark und muskulös aus... jetzt gebt doch mal ein bisschen an! Ja, lasst Eure Muskeln für mich spielen, <starker Mann/starke Frau>!\n\nWenn ich Euch angeben sehe, und auch nur dann, werde ich Euch etwas von dem leckeren Nugat aus Stormwind geben. Es ist eine großartige Schlotternachtssüßigkeit.", sourceObjective = "Ihr müsst vor Gastwirtin Allison angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Stormwind gibt!", progress = "Wenn Ihr nicht mit Euren Muskeln angeben wollt, gibt es nichts Süßes, {name}...", completion = "Ihr seid wirklich stark, haha! Gut gemacht, danke für die tolle Schau. Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8357] = { id = 8357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanzen für Marzipan", description = "Auch wenn Ihr einem kranken Kind beim Süßigkeitensammeln helft, so müsst Ihr mir noch immer etwas für Eure Belohnung vorführen! Man kann nicht so einfach mit der Tradition brechen, aber man kann...\n\nIch denke, dass ein Stück Marzipan heute eine ordentliche Tanzvorstellung wert ist! Ja genau, zeigt mal, was Ihr so drauf habt! Tanzt für mich und ich werde Euch etwas von dem leckeren Marzipan geben!", progress = "Ihr wisst doch wie man tanzt, oder? Rechter Fuß nach innen... dann nach außen... rechter Fuß nach innen... shake it Baby...", completion = "Ihr seid ganz schön tanzwütig, {name}!\n\nHier ist die Süßigkeit für Eure tolle Leistung. Gruselige Schlotternächte und sagt dem kranken Kindchen alles Gute von mir! Hoffentlich wird es bald wieder gesund.", objectives = "Tanzt für Gastwirtin Saelienne und Ihr werdet im Gegenzug etwas von dem Marzipan aus Darnassus bekommen!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8358] = { id = 8358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaugummikugelexpress", description = "Ah, Süßes oder Saures! Ja genau, Mann!\n\nNun, auch wenn Ihr etwas Ehrenhaftes tut und Süßigkeiten für ein krankes Kind sammelt, so kann ich Euch doch nicht so einfach davonkommen lassen. Ich hätte da eine leckere Kaugummikugel der Darkspear für das kranke Kind... wenn Ihr mir einen Zug vorführt! Haha, ja, das wär's! Der Preis für diese Kaugummikugel ist das Imitieren eines Zuges!\n\nTschugga-tschugga, {class}!", sourceObjective = "Ahmt für Kali Remik einen Zug nach und er wird Euch dafür eine Kaugummikugel der Darkspear geben!", progress = "Nun, legt los...", completion = "Huu-huu! Klasse, {name}! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[8359] = { id = 8359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muskelspiel für Nugat", description = "Das ist ein... interessantes Kostüm, welches Ihr da tragt. Auch wenn Ihr nett seid und einem kranken Kind dieses Jahr beim Süßigkeitensammeln helft, so fürchte ich doch, dass ich Euch um eine kleine Vorstellung bitten muss!\n\nMal sehen... Ihr seht in diesem... Kostüm stark und muskulös aus... jetzt gebt doch mal ein bisschen an! Ja, lasst Eure Muskeln für mich spielen, <starker Mann/starke Frau>!\n\nWenn ich Euch angeben sehe, und auch nur dann, werde ich Euch etwas von dem leckeren Nugat aus Orgrimmar geben. Es ist eine großartige Schlotternachtssüßigkeit.", sourceObjective = "Ihr müsst vor Gastwirtin Gryshka angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Stormwind gibt!", progress = "Wenn Ihr nicht mit Euren Muskeln angeben wollt, gibt es nichts Süßes, {name}...", completion = "Ihr seid wirklich stark, haha! Gut gemacht, danke für die tolle Schau. Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8360] = { id = 8360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanzen für Marzipan", description = "Auch wenn Ihr einem kranken Kind beim Süßigkeitensammeln helft, so müsst Ihr mir noch immer etwas für Eure Belohnung vorführen! Man kann nicht so einfach mit der Tradition brechen, aber man kann...\n\nIch denke, dass ein Stück Marzipan heute eine ordentliche Tanzvorstellung wert ist! Ja genau, zeigt mal, was Ihr so drauf habt! Tanzt für mich und ich werde Euch etwas von dem leckeren Marzipan geben!", sourceObjective = "Tanzt für Gastwirtin Pala und Ihr werdet im Gegenzug etwas von dem Marzipan aus Thunder Bluff bekommen!", progress = "Ihr wisst doch wie man tanzt, oder? Rechter Fuß nach innen... dann nach außen... rechter Fuß nach innen... shake it Baby...", completion = "Ihr seid ganz schön tanzwütig, {name}!\n\nHier ist die Süßigkeit für Eure tolle Leistung. Gruselige Schlotternächte und sagt dem kranken Kindchen alles Gute von mir! Hoffentlich wird es bald wieder gesund.", sourceObjectiveStatus = "unverified-source-field" }
quests[8361] = { id = 8361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssische Kontakte", description = "Wir haben Kultisten der Twilight-Hammer dabei beobachtet, wie sie mit Hilfe bizarrer Rituale mächtige Elementarfürsten beschworen haben. Noch wissen wir nicht, ob das die Wesen sind, die die Kultisten verehren, oder ob diese Wesen nur Botschafter einer weit größeren Macht sind. Eines wissen wir jedoch mit Sicherheit: von diesen Elementaren erhält der Kult seine Befehle.\n\nIch möchte, dass Ihr versucht, mit einem abyssischen Templer Kontakt aufzunehmen. Wenn Ihr das getan habt, verpasst ihm eine ordentliche Tracht Prügel! Nichts stürzt eine Organisation so sehr ins Chaos, wie eine Unterbrechung der Befehlskette. Oh, und vergesst nicht, mir einen Beweis für Euren Erfolg zu bringen!", sourceObjective = "Bor Wildmane auf Burg Cenarius in Silithus möchte, dass Ihr einen abyssischen Templer vernichtet und ihm dessen abyssisches Wappen als Beweis für Eure Tat bringt.", progress = "Habt Ihr Eure Aufgabe vollendet?", completion = "Hah! Ihr habt es geschafft, {name}! Schon bald werden die Twilight-Hammer besiegt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[8362] = { id = 8362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssische Wappen", progress = "Ihr habt Eure Fähigkeiten im Kampf mehrfach bewiesen, {name}. Wir müssen den Druck auf die Twilight-Hammer weiter aufrecht erhalten. Zieht los und bekämpft weitere abyssische Templer. Eure Mühen sollen nicht umsonst sein, und ich werde Euch mit einigen der Sachen entlohnen, die Huum und ich in der Schlacht erbeutet haben.", completion = "Ihr habt Euch hervorragend geschlagen! Und wieder einige Templer weniger, um die ich mir Sorgen machen muss.\n\nDas ist für Euch, {name}. Ich hoffe, dass Ihr einiges davon gebrauchen könnt." }
quests[8363] = { id = 8363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssische Siegel", progress = "Ihr habt bewiesen, dass Ihr mehr als fähig seid, es mit einem abyssischen Fürsten aufzunehmen, {name}. Ich fördere gerne jemanden, der sich als so tapfer erweist. Bringt mir mehr Siegelringe und ich werde Euch reichlich belohnen.", completion = "Sehr gut, {name}! Der Sieg über diese Fürsten, wird die Twilight-Hammer eine ganze Weile beschäftigen. Hier ist, wie versprochen, Eure Belohnung. Das sind einige der wertvolleren Gegenstände, die Huum und ich gefunden haben." }
quests[8364] = { id = 8364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssische Szepter", progress = "Ihr habt all meine Erwartungen bei weitem übertroffen, {name}. Ihr habt Euch Gegnern gestellt, bei denen Huum und ich lange und gründlichst über einen Angriff nachdenken würden. Das Beste, was ich in dieser Sache wohl tun kann, ist, Eure Bemühungen im Kampf gegen die Twilight-Hammer und ihre Oberanführer auch weiterhin zu belohnen. Bringt mir noch mehr abyssische Szepter und ich werde mein Bestes tun, um Euch gebührend zu entlohnen.", completion = "Ich habe gewusst, dass Ihr es schaffen würdet, {name}!  Hier ist Eure Belohnung." }
quests[8365] = { id = 8365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piratenhüte Ahoy!", description = "Ihr seid die Hilfe, die das Kartell entsandt hat? Ach, ich denke, Ihr werdet reichen. Hört mir genau zu, {class}. Wie Ihr wisst, bin ich die Lieferantin für modische Kleidung, die in den höchsten Kreisen der Gesellschaft Azeroths gefragt ist. Könige und Königinnen, Kriegshäuptlinge und... naja wie auch immer die Horde ihre Königinnen bezeichnet, all jene tragen, was ich als modisch deklariere. Und ich verdiene mir an ihnen eine goldene Nase, was natürlich das Beste am Ganzen ist.\n\nAlso hierfür benötige ich Eure Hilfe. Lauft hinunter zur Lost-Rigger-Bucht und beschafft mir einen Stapel Piratenhüte, koste es was es wolle. Glaubt Ihr, Ihr schafft das, hmm?", progress = "Habt Ihr alle 20 Hüte? Ich glaube Euch kein Wort, zeigt sie her. Ich hoffe für Euch, dass sie noch sauber und ganz sind!", completion = "Oh, Ihr seid ein Schatz, auch wenn Ihr etwas länger gebraucht habt, als ich es gewohnt bin. Diese Lieferung wird mir so einiges an Geld einbringen, sobald ich diese Hüte richtig gesäubert und individuell gestaltet habe. Hier habt Ihr etwas für Eure Mühen, Ihr habt Eure Aufgabe mit Bravour erledigt. Ich empfehle Euch allerdings, etwas von dem Geld für ein Bad auszugeben.", objectives = "Sammelt 20 Südmeerpiratenhüte und bringt sie zurück zur eingebildeten Modeschöpferin nach Steamwheedle in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8366] = { id = 8366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaunerei und Erpressung im Südmeer", description = "Argh! Sie verlangen das Unmögliche von mir!\n\nDas Steamwheedle-Kartell möchte, dass ich den Südmeerpiraten eine Lektion erteile. Ich kann doch aber nicht an zwei Orten gleichzeitig sein; Ich muss hierbleiben, um zumindest hier alles ruhig zu halten.\n\nSeit neuestem hält nicht mal mehr das Schutzgeld, dass das Kartell regelmäßig auszahlt, die Piraten auf. Daher möchte ich Euch zeitweilig abordnen, mal dort runter zu gehen und denen Saures zu geben.\n\nIhr findet die Piraten in der Lost-Rigger-Bucht, die hier gleich in der Nähe gen Süden ist. Besten Dank, {name}, ich schulde Euch was!", completion = "{name}! Ihr seid der Mann!!!\n\nIch bin mir sicher, dass das Kartell mir jetzt wieder freundlicher gestimmt sein wird, nun da Ihr mir mit dem Südmeerabschaum geholfen habt. Lasst mal sehen, womit könnte ich Euch belohnen? Und wenn ich Euch ein paar Münzen gäbe, damit Ihr Euch hier etwas aussucht? Na, seid Ihr damit einverstanden?", objectives = "Sicherheitschef Bilgewhizzle aus Steamwheedle in Tanaris beauftragt Euch, 10 Piraten der Südmeerfreibeuter, 10 Seeräuber der Südmeerfreibeuter, 10 Dockarbeiter der Südmeerfreibeuter und 10 Schwadroneure der Südseefreibeuter zu töten.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8367] = { id = 8367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Ehre", description = "Der Horde in einer der größten Schlachten gegen die Allianz zu dienen, ist das Ausschlaggebende für große Ehre! Die Wenigen jedoch, die der Horde auf ALL unseren aktiven Schlachtfeldern gedient haben, sind unsere wahren, großen Kämpfer. Unsere Gegner sollen besiegt werden, aber nicht mittels vereinzelter Gefechte, sondern durch einen gut koordinierten Krieg.\n\nGeht und schmettert die Allianz im Arathibecken, Alteractal und der Warsongschlucht nieder! Für Ehre! Für die Horde!", sourceObjective = "Bring je 3 Ehrenabzeichen des Alteractals, des Arathibeckens und der Warsongschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Arathi ist noch immer mit dem Blut großer Krieger getränkt und das Klirren von aufeinandertreffendem Stahl schallt durch das Alteractal. Verschwendet nicht meine Zeit, solange Ihr mir keine Neuigkeiten von der Front bringt!", completion = "Euer Unterfangen war nicht einfach, aber Euer Mut und Eure Stärke haben Euch nicht verlassen. Trennt Euch von alten Siegesabzeichen, {class}. Keiner soll sie als Beweis Eure Taten benötigen. Nehmt Haltung an, {name}. Heute werdet Ihr mit dem Stolz eines Helden erfüllt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[8368] = { id = 8368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht der Warsongschlucht", description = "Der Kampf gegen die Schildwachen der Silverwing in der Warsongschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, {name}! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", sourceObjective = "Bringt 3 Ehrenabzeichen der Warsong zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Überbringt Ihr Neuigkeiten von der Warsongschlucht, {name}?", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8369] = { id = 8369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasoren des Alteractals", description = "Hört mir genau zu, {name}. Egal, was auch immer Ihr über die noch immer tobende Schlacht im Alteractal gehört habt, etwas davon ist wahr: Es war die Expeditionsarmee der Stormpike, die diesen Konflikt durch die Besetzung des Territoriums der Frostwolf entfachte. Der Tag, an dem wir es der Allianz erlauben, Gebiete der Horde zu erobern, ohne militärisch zurückzuschlagen, wird der Tag sein, an dem ich meine Axt an den Nagel hänge, um den Rest meines Lebens in Schande zu verbringen. Geht jetzt und schlagt die Invasoren zurück!", progress = "Habt Ihr Neuigkeiten aus dem Lande der Frostwolf? Wie läuft die Schlacht im Alteractal?", completion = "Durch die Verteidigung unserer Ländereien im Alteractal habt Ihr Euren Mut bewiesen! Ich werde meinen Vorgesetzten von Euren Bemühungen berichten.", objectives = "Bringt 3 Ehrenabzeichen des Alteractals zu einem der Kriegshetzer der Horde, außerhalb der Schlachtfelder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8370] = { id = 8370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens", description = "Unser Konflikt mit der Allianz hat sich zu einem richtigen Krieg entwickelt. Es ist nicht länger notwendig unter falschen Vorwänden in die Schlacht zu ziehen, keine Seite erwartet dies noch länger.\n\n In der Schlacht um das Arathibecken geht es nur um eines, Ressourcen. Nicht mehr und nicht weniger. Entweder die Allianz erobert diese Ressourcen und benutzt sie gegen uns, oder wir kommen ihnen zuvor und verwenden die dortigen Ressourcenquellen für unsere Kriegspläne. {name}, helft den Entweihten dabei, die von uns benötigten Ressourcenlieferungen aufrecht zu erhalten!", progress = "Habt Ihr Neuigkeiten aus dem Arathibecken, {name}?", completion = "Die Sicherung unserer Ressourcen im Arathibecken ist eine lebenswichtige Aufgabe! Ihr habt sie gut gemeistert, {name}.", objectives = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
